 const grapplePanel=node('section','grapple-panel'),grapplePrompt=node('p'),grappleKeys=node('div','grapple-keys'),grappleActions=node('div','grapple-buttons');grapplePanel.hidden=true;grapplePanel.append(grapplePrompt,grappleKeys,grappleActions);stage.append(grapplePanel);for(const k of ['W','A','S','D'])grappleActions.append(btn(k,()=>grapplePress(k)));function grapplePress(k){if(paused||document.hidden||!alive)return;const result=grapple.press(k);if(result==='success'){tone(880,.4,'sine',.04);say('大立人神光觉醒，怨影退散','청동대립인의 빛이 깨어나요. 원혼이 물러가요');}renderGrapple();}function renderGrapple(){const g=grapple.state;if(!g)return;grapplePrompt.textContent=g.phase==='qte'?bi('依次按键或点击 · '+g.left.toFixed(1)+'秒','순서대로 키 또는 버튼 · '+g.left.toFixed(1)+'초'):g.phase==='repel'?bi('神光正在驱退怨影…','신성한 빛이 원혼을 물리쳐요…'):g.phase==='failed'?bi('理智 −15 · 正在脱离','정신력 −15 · 벗어나는 중'):bi('本次限时 '+g.limit.toFixed(1)+' 秒 · 追杀越久时间越短 · P暂停','이번 제한 '+g.limit.toFixed(1)+'초 · 추격이 길수록 짧아져요 · P 일시정지');grappleKeys.textContent=g.sequence.map((k,i)=>i<g.index?'✓':k).join('  →  ');grappleKeys.hidden=g.phase==='repel'||g.phase==='failed';grappleActions.hidden=g.phase!=='qte';for(const b of grappleActions.children)b.disabled=paused;}
